-- Run this once in Supabase Studio (SQL Editor) for the KANJI project
-- (https://ltxqagtohxzjfrztbbdq.supabase.co).
--
-- Adds "いろどり" (Irodori) textbook vocabulary to the existing `vocab_db`
-- table, alongside the "Minna no Nihongo" rows already seeded there. Both
-- sources share the vocab_db table (and the vocab-n5/vocab-n4 flashcard
-- category) but render differently in the app based on the new `source`
-- column -- Irodori cards show the kana reading on the front and the kanji
-- form + meaning on the back, plus part-of-speech / book badges.
--
-- Book -> JLPT-equivalent mapping used below (Irodori targets CEFR A1-A2,
-- roughly matching N5-N4): 入門 + 初級1 -> N5, 初級2 -> N4.
--
-- Source data: D:\OneDrive用領域\OneDrive\Desktop\wordlist_all.xlsx,
-- deduplicated (3685 of 4246 rows kept, first pedagogical occurrence wins)
-- and English glosses machine-translated to Vietnamese.

alter table public.vocab_db add column if not exists source text not null default 'minna';
alter table public.vocab_db add column if not exists kanji_form text;
alter table public.vocab_db add column if not exists part_of_speech text;
alter table public.vocab_db add column if not exists book_label text;

-- Idempotent: safe to re-run without creating duplicate Irodori rows.
delete from public.vocab_db where source = 'irodori';

